-- Retain exact pre-start self-cleanup in the original journal. Host deadline
-- control uses the original process clock, never a mapped guest timestamp.
LOCK TABLE occ.turn_journal_operations IN ACCESS EXCLUSIVE MODE;
ALTER TABLE occ.turn_journal_operations DROP CONSTRAINT turn_journal_operations_kind;
ALTER TABLE occ.turn_journal_operations ADD CONSTRAINT turn_journal_operations_kind
  CHECK (operation_kind IN ('checkpoint-allocation','completion','outcome','cancellation','release',
    'execution-intent','execution-start','execution-interruption','deadline-control'));
DROP INDEX occ.turn_journal_execution_once;
CREATE UNIQUE INDEX turn_journal_execution_once ON occ.turn_journal_operations
  (installation_id,namespace_id,agent_id,conversation_ref,turn_ref,attempt_ref,reservation_ref,operation_kind)
  WHERE operation_kind IN ('execution-intent','execution-start','execution-interruption','deadline-control');
CREATE UNIQUE INDEX turn_journal_native_construction ON occ.turn_journal_operations
  (installation_id,(request->>'nativeIncarnationRef'),(request->>'nativeConstructionRef'))
  WHERE operation_kind='deadline-control';

